import React from "react";
import { useCart } from "../components/CartContext";
import { useNavigate } from "react-router-dom";


const Cart = () => {
  const { cartItems, updateQuantity, removeFromCart } = useCart();

  const totalPrice = cartItems.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );
  const navigate = useNavigate();


  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Your Cart 🛒</h2>

      {cartItems.length === 0 ? (
        <p style={styles.empty}>No items in the cart.</p>
      ) : (
        <>
          <ul style={styles.list}>
            {cartItems.map((item, index) => (
              <li key={index} style={styles.item}>
                <div style={styles.itemDetails}>
  <img
  src={`http://localhost:5000/uploads/${item.image}`}
  alt={item.name}
  style={styles.itemImage}
/>

  <div>
    <strong>{item.name}</strong>
    <p>₹{item.price} each</p>
  </div>
</div>


                <div style={styles.controls}>
                  <button
                    onClick={() =>
                      updateQuantity(item._id, Math.max(item.quantity - 1, 1))
                    }
                    style={styles.btn}
                  >
                    –
                  </button>
                  <span style={styles.qty}>{item.quantity}</span>
                  <button
                    onClick={() => updateQuantity(item._id, item.quantity + 1)}
                    style={styles.btn}
                  >
                    +
                  </button>
                </div>

                <div style={styles.remove}>
                  <button
                    onClick={() => removeFromCart(item._id)}
                    style={styles.removeBtn}
                  >
                    
                  </button>
                </div>
              </li>
            ))}
          </ul>

          <h3 style={styles.total}>Total: ₹{totalPrice}</h3>

          <button style={styles.checkoutBtn}>Proceed to Checkout</button>
          <button
  style={styles.continueBtn}
  onClick={() => navigate("/products")}
>
  Continue Shopping 
</button>

        </>
        
      )}
      
    </div>
  );
};

const styles = {
  container: {
    padding: "48px 24px",
    maxWidth: "900px",
    margin: "32px auto",
    background: "var(--color-surface-blur)",
    borderRadius: "24px",
    boxShadow: "0 8px 32px rgba(58,63,239,0.10)",
    backdropFilter: "var(--color-glass-blur)",
    WebkitBackdropFilter: "var(--color-glass-blur)",
  },
  heading: {
    fontSize: "2rem",
    marginBottom: "24px",
    color: "var(--color-primary)",
    fontWeight: 800,
    letterSpacing: 0.5,
  },
  empty: {
    fontSize: "18px",
    color: "var(--color-text-secondary)",
    opacity: 0.8,
    margin: "32px 0",
  },
  list: {
    listStyle: "none",
    padding: 0,
    margin: 0,
  },
  item: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    borderBottom: "1.5px solid var(--color-border)",
    padding: "22px 0",
    background: "var(--color-surface)",
    borderRadius: "16px",
    marginBottom: "18px",
    boxShadow: "0 2px 8px rgba(58,63,239,0.06)",
    transition: "box-shadow 0.2s, transform 0.2s",
  },
  name: {
    flex: 2,
  },
  controls: {
    display: "flex",
    alignItems: "center",
    gap: "12px",
  },
  btn: {
    padding: "7px 16px",
    fontSize: "18px",
    cursor: "pointer",
    background: "linear-gradient(90deg, var(--color-primary) 0%, var(--color-accent) 100%)",
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    fontWeight: 700,
    transition: "background 0.3s, transform 0.2s",
    boxShadow: "0 2px 8px rgba(0,224,211,0.08)",
  },
  btnHover: {
    background: "linear-gradient(90deg, var(--color-accent) 0%, var(--color-primary) 100%)",
    transform: "scale(1.04)",
  },
  qty: {
    fontSize: "16px",
    fontWeight: "700",
    padding: "0 8px",
  },
  remove: {
    marginLeft: "10px",
  },
  removeBtn: {
    background: "transparent",
    border: "none",
    fontSize: "22px",
    cursor: "pointer",
    color: "var(--color-danger)",
    fontWeight: 700,
    transition: "color 0.2s, transform 0.2s",
  },
  total: {
    marginTop: "36px",
    fontSize: "24px",
    color: "var(--color-primary)",
    fontWeight: 800,
    letterSpacing: 0.5,
  },
  checkoutBtn: {
    marginTop: "22px",
    padding: "16px 32px",
    background: "linear-gradient(90deg, var(--color-primary) 0%, var(--color-accent) 100%)",
    color: "#fff",
    fontSize: "18px",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    fontWeight: 800,
    transition: "background 0.3s, transform 0.2s",
    boxShadow: "0 2px 8px rgba(0,224,211,0.08)",
    letterSpacing: 0.5,
  },
  continueBtn: {
    marginTop: "14px",
    padding: "12px 28px",
    background: "linear-gradient(90deg, var(--color-accent) 0%, var(--color-primary) 100%)",
    color: "#fff",
    fontSize: "16px",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    fontWeight: 700,
    transition: "background 0.3s, transform 0.2s",
    boxShadow: "0 2px 8px rgba(0,224,211,0.08)",
    marginLeft: "10px",
    letterSpacing: 0.5,
  },
  itemDetails: {
    display: "flex",
    alignItems: "center",
    gap: "18px",
    flex: 2,
  },
  itemImage: {
    width: "80px",
    height: "80px",
    objectFit: "cover",
    borderRadius: "12px",
    border: "1.5px solid var(--color-border)",
    background: "var(--color-bg)",
    boxShadow: "0 2px 8px rgba(58,63,239,0.06)",
  },
};

export default Cart;
